-- 2. Main: all sections ------------------------------------------------------------------
with r as (

select 21 as section_no, 'MAXIMUS' as project, 'M1' as member,
       table_type, 'SATELLITE  SAT_ASSESSMENT_HEADER' as section_object,
       rows_in_scope, null_load_datetime, null_record_source, null_dbt_run_ts, placeholder_load_datetime, future_load_datetime, load_after_run_ts, unexpected_record_source,
       iff(status = 'FAIL', 1, 0) as failing_rows,
       status,
       nullif(array_to_string(array_construct_compact(
           iff(rows_in_scope = 0, '0 rows in scope', null),
           iff(null_load_datetime > 0, 'null_load_datetime=' || null_load_datetime, null), iff(null_record_source > 0, 'null_record_source=' || null_record_source, null), iff(null_dbt_run_ts > 0, 'null_dbt_run_ts=' || null_dbt_run_ts, null), iff(placeholder_load_datetime > 0, 'placeholder_load_datetime=' || placeholder_load_datetime, null), iff(future_load_datetime > 0, 'future_load_datetime=' || future_load_datetime, null), iff(load_after_run_ts > 0, 'load_after_run_ts=' || load_after_run_ts, null), iff(unexpected_record_source > 0, 'unexpected_record_source=' || unexpected_record_source, null),
           iff(array_size(unexpected_examples) > 0,
               'unexpected examples: ' || array_to_string(unexpected_examples, ', '), null)), '; '), '') as remarks
  from (
        select 'MAXIMUS' as project, 'satellite' as table_type, 'SAT_ASSESSMENT_HEADER' as table_name,
               count(*) as rows_in_scope,
               count_if(LOAD_DATETIME is null) as null_load_datetime,
               count_if(nullif(trim(RECORD_SOURCE), '') is null) as null_record_source,
               null as null_dbt_run_ts,
               count_if(LOAD_DATETIME < '1990-01-01') as placeholder_load_datetime,
               count_if(LOAD_DATETIME > dateadd(day, 1, current_timestamp()::timestamp_ntz)) as future_load_datetime,
               null as load_after_run_ts,
               count_if(not (RECORD_SOURCE in ('MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS'))) as unexpected_record_source,
               array_slice(array_agg(distinct iff(not (RECORD_SOURCE in ('MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS')), RECORD_SOURCE, null)), 0, 5) as unexpected_examples,
               iff(null_load_datetime = 0 and null_record_source = 0 and coalesce(null_dbt_run_ts, 0) = 0
                   and placeholder_load_datetime = 0 and future_load_datetime = 0 and coalesce(load_after_run_ts, 0) = 0
                   and coalesce(unexpected_record_source, 0) = 0, 'PASS', 'FAIL') as status
          from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_ASSESSMENT_HEADER
         where RECORD_SOURCE in ('MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS')
  )

